func TestGeneratedLinkCalls(t *testing.T) {
	document, err := compiler.Compile([]byte(`{"openapi":"3.1.0","info":{"title":"Links","version":"1"},"paths":{"/todos":{"post":{"operationId":"createTodo","x-envelope":"data","parameters":[{"name":"X-Correlation","in":"header","schema":{"type":"string"},"required":false}],"requestBody":{"required":true,"content":{"application/json":{"schema":{"type":"object","properties":{"title":{"type":"string"}},"required":["title"],"additionalProperties":false}}}},"responses":{"201":{"description":"Done","content":{"application/json":{"schema":{"type":"object","properties":{"data":{"type":"object","properties":{"id":{"type":"string"},"enabled":{"type":"boolean"},"count":{"type":"number"},"a/b":{"type":"object","properties":{"~key":{"type":"array","items":{"type":"string"}}},"required":["~key"],"additionalProperties":false}},"required":["id","enabled","count","a/b"],"additionalProperties":false},"meta":{"type":"string"}},"required":["data","meta"],"additionalProperties":false}}},"links":{"GetTodo":{"operationId":"getTodo","parameters":{"todoID":"$response.body#/data/id","enabled":"$response.body#/data/enabled","count":"$response.body#/data/count","q":"$request.body#/title","X-Next":"$response.header.X-Token","pointer":"$response.body#/data/a~1b/~0key/0"}},"UpdateTodo":{"operationId":"updateTodo","parameters":{"todoID":"$response.body#/data/id"},"requestBody":{"title":"default","enabled":true,"count":1}},"FromHeader":{"operationId":"getTodo","parameters":{"todoID":"$request.header.X-Correlation"}}}},"409":{"description":"Done","content":{"application/json":{"schema":{"type":"object","properties":{"data":{"type":"object","properties":{"id":{"type":"string"},"enabled":{"type":"boolean"},"count":{"type":"number"},"a/b":{"type":"object","properties":{"~key":{"type":"array","items":{"type":"string"}}},"required":["~key"],"additionalProperties":false}},"required":["id","enabled","count","a/b"],"additionalProperties":false},"meta":{"type":"string"}},"required":["data","meta"],"additionalProperties":false}}},"links":{"GetTodo":{"operationId":"getTodo","parameters":{"todoID":"$response.body#/data/id","enabled":"$response.body#/data/enabled","count":"$response.body#/data/count","q":"$request.body#/title","X-Next":"$response.header.X-Token","pointer":"$response.body#/data/a~1b/~0key/0"}},"UpdateTodo":{"operationId":"updateTodo","parameters":{"todoID":"$response.body#/data/id"},"requestBody":{"title":"default","enabled":true,"count":1}},"FromHeader":{"operationId":"getTodo","parameters":{"todoID":"$request.header.X-Correlation"}}}}}}},"/todos/{todoID}":{"get":{"operationId":"getTodo","parameters":[{"name":"todoID","in":"path","schema":{"type":"string"},"required":true},{"name":"q","in":"query","schema":{"type":"string"},"required":false},{"name":"enabled","in":"query","schema":{"type":"boolean"},"required":false},{"name":"count","in":"query","schema":{"type":"number"},"required":false},{"name":"pointer","in":"query","schema":{"type":"string"},"required":false},{"name":"X-Next","in":"header","schema":{"type":"string"},"required":false}],"responses":{"200":{"description":"Done","content":{"application/json":{"schema":{"type":"object","properties":{"path":{"type":"string"},"query":{"type":"string"},"header":{"type":"string"}},"required":["path","query","header"],"additionalProperties":false}}}}}},"patch":{"operationId":"updateTodo","parameters":[{"name":"todoID","in":"path","schema":{"type":"string"},"required":true}],"requestBody":{"required":true,"content":{"application/json":{"schema":{"type":"object","properties":{"title":{"type":"string"},"enabled":{"type":"boolean"},"count":{"type":"number"}},"required":["title","enabled","count"],"additionalProperties":false}}}},"responses":{"200":{"description":"Done","content":{"application/json":{"schema":{"type":"object","properties":{"path":{"type":"string"},"query":{"type":"string"},"header":{"type":"string"}},"required":["path","query","header"],"additionalProperties":false}}}}}}}}}`))
	if err != nil {
		t.Fatal(err)
	}
	plan, diagnostics, err := (Generator{}).Prepare(document, generator.Options{Golang: &generator.GoOptions{ImportPath: "example.test/consumer/api"}})
	if err != nil || len(diagnostics) != 0 {
		t.Fatalf("prepare %v %v", err, diagnostics)
	}
	testGeneratedModule(t, plan, map[string]string{"link_test.go": linkConsumer})
}

const linkConsumer = `package consumer_test
import("context";"encoding/json";"errors";"net/http";"net/http/httptest";"net/url";"sync/atomic";"testing";sdk "example.test/consumer/api";"example.test/consumer/api/types")
func TestLinkInputsAndHTTPErrorSources(t *testing.T){
 var requests atomic.Int32;var conflict atomic.Bool
 server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){requests.Add(1);w.Header().Set("Content-Type","application/json");if r.URL.Path=="/todos"{w.Header().Set("X-Token","token");if conflict.Load(){w.WriteHeader(409)}else{w.WriteHeader(201)};json.NewEncoder(w).Encode(map[string]any{"data":map[string]any{"id":"todo/1","enabled":false,"count":0,"a/b":map[string]any{"~key":[]string{"pointer"}}},"meta":"preserve"});return};if r.Method=="PATCH"{var body struct{Title string;Enabled bool;Count float64};if err:=json.NewDecoder(r.Body).Decode(&body);err!=nil{t.Error(err)};if body.Title!="default"||body.Enabled||body.Count!=0{t.Error("body override merge lost presence",body)}};json.NewEncoder(w).Encode(map[string]any{"path":r.URL.EscapedPath(),"query":r.URL.RawQuery,"header":r.Header.Get("X-Next")})}));defer server.Close()
 client,err:=sdk.NewClient(sdk.ClientOptions{BaseURL:server.URL});if err!=nil{t.Fatal(err)};input:=sdk.CreateTodoInput{Header:types.Some(sdk.CreateTodoHeader{XCorrelation:types.Some("header-id")}),Body:sdk.CreateTodoBody{Title:"source title"}}
 source,err:=client.Operations.CreateTodo(input).Raw(context.Background());if err!=nil{t.Fatal(err)};source.Status=500;source.Headers.Set("X-Token","mutated");source.Data=types.Value{};source.Request.URL.Path="/mutated";source.OriginalResponse.Header.Set("X-Token","mutated")
 before:=requests.Load();follow:=client.Links.CreateTodo.GetTodo.Follow(source,sdk.CreateTodoGetTodoLinkInvocation{SourceInput:types.Some(input),Input:types.Some(sdk.GetTodoLinkOverride{Query:types.Some(sdk.GetTodoLinkOverrideQuery{Q:types.Some("override"),Enabled:types.Some(false),Count:types.Some(float64(0))})})});if requests.Load()!=before{t.Fatal("Follow performed HTTP")};result,err:=follow.Do(context.Background());if err!=nil{t.Fatal(err)};query,err:=url.ParseQuery(result.Query);if err!=nil||result.Path!="/todos/todo%2F1"||query.Get("q")!="override"||query.Get("enabled")!="false"||query.Get("count")!="0"||query.Get("pointer")!="pointer"||result.Header!="token"{t.Fatal("full original source, pointer and override",result,query,err)}
 update:=client.Links.CreateTodo.UpdateTodo.ByStatus201.Follow(source,sdk.CreateTodoUpdateTodoLinkInvocationFor201{Input:types.Some(sdk.UpdateTodoLinkOverride{Body:types.Some(sdk.UpdateTodoLinkOverrideBody{Enabled:types.Some(false),Count:types.Some(float64(0))})})});if _,err:=update.Do(context.Background());err!=nil{t.Fatal(err)}
 header,err:=client.Links.CreateTodo.FromHeader.Follow(source,sdk.CreateTodoFromHeaderLinkInvocation{SourceInput:types.Some(input)}).Do(context.Background());if err!=nil||header.Path!="/todos/header-id"{t.Fatal("source input header",header,err)}
 before=requests.Load();if _,err:=client.Links.CreateTodo.FromHeader.Follow(source).Do(context.Background());err==nil||requests.Load()!=before{t.Fatal("missing source input sent request",err)}
 var zero sdk.CreateTodoRawResponse;if _,err:=client.Links.CreateTodo.GetTodo.Follow(&zero).Do(context.Background());err==nil||requests.Load()!=before{t.Fatal("fabricated HTTP source accepted",err)}
 conflict.Store(true);_,err=client.Operations.CreateTodo(input).Raw(context.Background());var failure *sdk.CreateTodoHTTPError;if !errors.As(err,&failure){t.Fatal(err)};linked,err:=client.Links.CreateTodo.GetTodo.Follow(failure).Do(context.Background());if err!=nil||linked.Path!="/todos/todo%2F1"{t.Fatal("HTTP error source",linked,err)}
}
`
